INSERT INTO public.projects(id,name,category,filter_group,description,technologies,github_url,figma_url,live_url,image_url,image_alt,featured,published,sort_order,status,problem,solution,features) VALUES
('riaya','Ri''aya','Healthcare Technology / Web Application','Web','A healthcare workflow platform designed to improve coordination and communication between hospital departments and medical staff. A team project that advanced to the final stage of a competition.','{HTML,CSS,JavaScript,Supabase,PostgreSQL,Supabase Realtime,Supabase Authentication,Supabase Storage}','https://github.com/ahmadabutouq060-cmd/Riaya-Website','','https://riaya-website.vercel.app','/__l5e/assets-v1/4d758c17-9de0-4e8b-b37f-3fb049c8f217/riaya-live-home.png','Ri’aya sign-in screen from the original project',true,true,0,'Team project · Competition finalist','Hospital departments each work in their own silo, so patient requests and results have to be chased manually between teams.','One authenticated platform with role-based dashboards and realtime communication across hospital departments. AI assists, doctors decide.','{Role-based dashboards,Laboratory requests and follow-up,Blood bank request workflows,Realtime communication,Notifications,Shift scheduling,AI-assisted insights,Admin management of doctors and departments,Doctor dashboards with chat and patient lists,Browser document OCR and PDF rendering,Installable PWA with automatic idle logout}'),
('aushop','AUShop','Desktop Application','Desktop','A JavaFX desktop shop application backed by a MySQL/MariaDB database, built as a university course project in NetBeans.','{Java,JavaFX,JDBC,MySQL / MariaDB,SQL}','https://github.com/ahmadabutouq060-cmd/AUShop','','','','',false,true,1,'Course project','Managing a small shop’s users, products and orders from spreadsheets leaves no single place to place an order, track its status or collect customer feedback.','A single JavaFX application connected to the au_shop database over JDBC, where users sign in and browse or manage products, orders and feedback.','{Login with database user roles,Product catalogue with category and price and stock,Order placement with quantity and total and status,Customer feedback with rating and message,Included MySQL/MariaDB schema}'),
('expenses','Flutter Expense Tracker','Mobile Application','Mobile','A Flutter expense tracker where spending is added by category and visualised in a bar chart.','{Flutter,Dart,Material Design,uuid,intl}','https://github.com/ahmadabutouq060-cmd/Flutter-App','','','','',false,true,2,'Completed','A plain expense list says little about where day-to-day spending goes.','A single-screen app keeps expenses in app state and renders them as a list and a category bar chart.','{Add an expense with title and amount and date and category,Remove an expense with an undo action,Category bar chart summarising spending}'),
('dice','Dice Roller','Mobile Development / Learning','Mobile','A practical Flutter learning project with dice images and a roll button, demonstrating mobile development fundamentals.','{Flutter,Dart}','https://github.com/ahmadabutouq060-cmd/dice','','','','',false,true,3,'Learning project','','','{Custom gradient container widget,Dice face images swapped from a widget action,Reusable styled text widget}'),
('rikaz','Rikaz (ركاز)','UI/UX Design','Design','A Figma design exploring a mascot-style character and icon variations, with multiple frames and states laid out side by side.','{Figma}','','https://www.figma.com/design/lrxHpuwZDZ2qEoRqIoQa8g/%D8%B1%D9%83%D8%A7%D8%B2?node-id=0-1','','','Overview of the Rikaz Figma design file',false,true,4,'Design project','','','{}'),
('funriro','Funriro','UI/UX Design','Design','A Figma design project.','{Figma}','','','','','',false,true,5,'Design project','','','{}');
INSERT INTO public.site_settings(id,content) VALUES(1,'{"name":"Ahmad Abu Touq","title":"Software Engineering Student & Developer","heroText":"I build practical digital products through software engineering, mobile development, and thoughtful problem-solving.","about":"I’m a Software Engineering student at Applied Science Private University in Amman, Jordan. I enjoy turning ideas into practical software products through academic and hands-on projects. My interests span mobile and backend development, with UI/UX as a complementary strength. I’m continually learning, building, and refining the way I work.","university":"Applied Science Private University","graduation":"September 2028","email":"ahmadabutouq116@gmail.com","github":"https://github.com/ahmadabutouq060-cmd","linkedin":"https://www.linkedin.com/in/ahmad-abu-touq/","focus":["Advanced Flutter Development","Backend Development","Software Architecture","Building practical software products"]}');
